function unequalTriplets(nums) {
  const count = new Map();
  for (const num of nums) {
    count.set(num, (count.get(num) || 0) + 1);
  }

  const n = nums.length;
  let before = 0;
  let answer = 0;
  for (const group of count.values()) {
    const after = n - before - group;
    answer += before * group * after;
    before += group;
  }
  return answer;
}

