function generate(rand, size) {
  if (size === 'large') {
    const spread = [3, 10, 50, 1000][Math.floor(rand() * 4)];
    return [Array.from({ length: 100 }, () => 1 + Math.floor(rand() * spread))];
  }
  const n = 3 + Math.floor(rand() * 8);
  const spread = rand() < 0.2 ? 1000 : 1 + Math.floor(rand() * 5);
  return [Array.from({ length: n }, () => 1 + Math.floor(rand() * spread))];
}
